contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public payable {
        require(changeTolerance < 100, "input tolerance too high");

        (, uint256 beforeEpochSize, , uint8 beforeTolerance) = c.security();

        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (, uint256 afterEpochSize, , uint8 afterTolerance) = c.security();

        assert(
            reverted
                ? (afterEpochSize == beforeEpochSize && afterTolerance == beforeTolerance)
                : (afterEpochSize == epochSize && afterTolerance == changeTolerance)
        );
    }
}

