contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address asset, uint256 amount, uint256 unlockTime) public payable {
        if (amount > 0 && unlockTime == 0) {
            c.configureFlashGovernance(asset, amount, 0, false);
        }

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 recordedAmount;
        uint256 recordedUnlock;
        address recordedAsset;
        if (amount > 0 && unlockTime == 0) {
            (recordedAmount, recordedUnlock, recordedAsset, ) = c.pendingFlashDecision(targetContract, address(this));
        }

        bool preExists = (recordedAmount > 0 && recordedAsset == asset && unlockTime < block.timestamp);

        assert(reverted == !preExists);
    }

    receive() external payable {}
}

