contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address asset) public payable {
        // Read the pending decision from the public mapping getter before the deciding call.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, ) =
            c.pendingFlashDecision(targetContract, address(this));

        // The decision call under test.
        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: it reverts iff no valid, matured pending decision exists for msg.sender.
        bool hadPending = beforeAsset == asset && beforeAmount > 0 && beforeUnlockTime < block.timestamp;

        assert(reverted == !hadPending);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address asset, uint256 unlockTime) public payable {
        // Configure the pending decision directly through the public surface by reading
        // what the getter already exposes. If a matching, matured pending decision exists
        // before the call, the call must succeed; otherwise it must revert.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, ) =
            c.pendingFlashDecision(targetContract, address(this));

        bool hadPending =
            beforeAsset == asset &&
            beforeAmount > 0 &&
            beforeUnlockTime < block.timestamp;

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == !hadPending);
    }

    receive() external payable {}
}

