contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 v1, uint256 v2) public payable {
        // Activation attempt on behalved of this test contract.
        c.setEnforcement(true);

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        ( , , uint8 changeTolerance) = c.security();

        bool exceeds;
        if (v1 > v2) {
            exceeds = v2 == 0 ? v1 > 1 : (v1 - v2) * 100 >= changeTolerance * v1;
        } else {
            exceeds = v1 == 0 ? v2 > 1 : (v2 - v1) * 100 >= changeTolerance * v1;
        }

        // If enforcement is active, reverting exactly when the tolerance is exceeded prevents underflow in the test.
        assert(reverted == exceeds);
    }

    receive() external payable {}
}

