contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address dao, bool endConfigurationFirst) public {
        // Optionally end configuration first to make the require condition stricter/looser.
        // Calling endConfiguration is a public state-changing entry, so it must be a top-level call.
        if (endConfigurationFirst) {
            c.endConfiguration();
        }

        // Snapshot before-value of DAO.
        address oldDAO = c.DAO();

        // Precondition matching the contract's require in setDAO:
        // DAO == address(0) || msg.sender == DAO || !configured
        // msg.sender is address(this); we cannot be DAO unless DAO was pre-set to address(this).
        // Only attempt the call when it should succeed.
        bool configured = c.configured();
        bool allowed = oldDAO == address(0) || oldDAO == address(this) || !configured;
        require(allowed, "precondition: setDAO would revert");

        // The deciding call.
        c.setDAO(dao);

        // General rule: after a successful setDAO, DAO is exactly the new address.
        assert(c.DAO() == dao);
    }
}

