    }

    function run(uint8 maxChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public {
        uint256 beforeChange;
        uint256 beforeEpoch;
        uint256 beforeTolerance;
        (beforeChange, beforeEpoch, , beforeTolerance) = c.security();

        bool reverted;
        try c.configureSecurityParameters(maxChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // Revert must be justified either by tolerance validation or by proposal authorization
            assert(changeTolerance >= 100 || !c.configured());
        } else {
            // Success must mean tolerance was valid and authorization passed
            assert(changeTolerance < 100 && c.configured());

            uint256 afterChange;
            uint256 afterEpoch;
            uint256 afterTolerance;
            (afterChange, afterEpoch, , afterTolerance) = c.security();

            // On success, the stored values must exactly match the supplied parameters.
            assert(
                afterChange == uint256(maxChangePerEpoch) &&
                afterEpoch == epochSize &&
                afterTolerance == uint256(changeTolerance)
            );
        }
    }
}

