            // mean the values were outside the tolerance limits.
            uint256 uv1 = v1;
            uint256 uv2 = v2;
            bool withinTolerance;
            if (uv1 > uv2) {
                if (uv2 == 0) {
                    withinTolerance = uv1 <= 1;
                } else {
                    withinTolerance = ((uv1 - uv2) * 100) < 100 * uv1;
                }
            } else {
                if (uv1 == 0) {
                    withinTolerance = uv2 <= 1;
                } else {
                    withinTolerance = ((uv2 - uv1) * 100) < 100 * uv1;
                }
            }
            assert(!reverted || !withinTolerance);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 tolerance, uint256 epochSize, uint8 maxChange, uint256 v1, uint256 v2, bool activateEnforcement) public {
        // Configure security parameters via onlySuccessfulProposal path.
        c.configureSecurityParameters(maxChange, epochSize, tolerance);

        // Optionally set enforcement active for this test contract as caller.
        c.setEnforcement(activateEnforcement);

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Determine whether the caller is in the enforcing state:
        // enforcement only takes effect when the caller exposes configured() == true.
        // InvMutTest itself does not implement configured(), so Configurable(caller).configured()
        // would revert; we rely on the public getter enforceLimitsActive and the fact that this
        // test contract is not a Configurable, meaning the call must not revert.
        bool enforcementActiveRead = c.enforceLimitsActive(address(this));

        // The caller (this test contract) is not a Configurable contract; therefore the
        // internal guard `!Configurable(msg.sender).configured()` is never satisfied and
        // enforceTolerance must always complete without reverting.
        assert(!enforcementActiveRead || !reverted);

        // A stronger general rule: regardless of enforcement flag or security parameters,
        // enforceTolerance never reverts for a non-Configurable caller.
        assert(!reverted);
    }

    receive() external payable {}
}

