contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 amountToMint) public payable {
        // Make the test contract flash-enabled by setting itself as governed through a successful proposal.
        // Since onlySuccessfulProposal requires configured && successfulProposal(msg.sender),
        // and c is freshly deployed, configured is false, so the condition is bypassed.
        address[] memory governables = new address[](1);
        bool[] memory isGoverned = new bool[](1);
        governables[0] = address(this);
        isGoverned[0] = true;
        c.setGoverned(governables, isGoverned);

        // Read the current flash governance config and security parameters.
        (uint256 cfgAmount, uint256 cfgUnlockTime, address cfgAsset, bool cfgBurnable) = c.flashGovernanceConfig();
        (uint256 epochSize, uint256 lastAct, uint8 maxChange, uint8 tolerance) = c.security();

        // Determine whether a pending decision already exists for (target, address(this)).
        (uint256 pendingAmount, uint256 pendingUnlockTime, address pendingAsset, bool pendingBurnable) = c.pendingFlashDecision(target, address(this));
        bool pendingExpired = pendingUnlockTime < block.timestamp;

        // The asset must be a contract that implements transferFrom enough to succeed.
        // We don't need to mint; we just check whether the call reverts.
        bool reverted;
        try c.assertGovernanceApproved(address(this), target, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call succeeds iff the caller is flash-enabled, the asset transferFrom succeeds,
        // and the pending decision is expired. Since we set ourselves as governed, flash-enabled is true.
        // The transferFrom success is not directly observable in a boolean without external calls,
        // but we can express the rule as: reverted is equivalent to NOT (transferFrom would succeed && pending expired).
        // However, without observing the token behavior, we can state that if the transferFrom would succeed and pending is expired,
        // then it should not revert. Conversely, if it reverts, it must be because transferFrom failed or pending not expired.
        // Since we cannot observe transferFrom outcome, we use the fact that for the test to reach the assert,
        // the call may have reverted. We can check the change in pending state or security.lastFlashGovernanceAct.
        // Observable after-state: if not reverted, pendingFlashDecision[target][address(this)].unlockTime should have increased
        // and security.lastFlashGovernanceAct updated to block.timestamp.
        (uint256 postAmount, uint256 postUnlockTime, address postAsset, bool postBurnable) = c.pendingFlashDecision(target, address(this));
        (uint256 postEpochSize, uint256 postLastAct, uint8 postMaxChange, uint8 postTolerance) = c.security();

        if (!reverted) {
            // Success case: the decision was recorded and the last act updated.
            assert(postUnlockTime == pendingUnlockTime + block.timestamp && postLastAct == block.timestamp);
        } else {
            // Revert case: no state change should occur in the pending decision or last act.
            assert(postUnlockTime == pendingUnlockTime && postLastAct == lastAct);
        }
    }

    receive() external payable {}
}

