contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint8 maxChange, uint256 epochSize, uint8 changeTolerance) public {
        // The only revert condition in configureSecurityParameters is changeTolerance >= 100.
        // It also has onlySuccessfulProposal, which under a fresh instance (configured == false)
        // is satisfied because assertSuccessfulProposal short-circuits when !configured.
        bool reverted;
        try c.configureSecurityParameters(maxChange, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 readMax, uint256 readEpochSize, uint256 readTolerance) = c.security();

        if (changeTolerance >= 100) {
            // Must revert and must leave security unchanged (all zero at fresh deploy).
            assert(reverted);
            assert(readMax == 0 && readEpochSize == 0 && readTolerance == 0);
        } else {
            // Must not revert and must set all three fields to exactly the supplied arguments.
            assert(!reverted);
            assert(readMax == uint256(maxChange));
            assert(readEpochSize == epochSize);
            assert(readTolerance == uint256(changeTolerance));
        }
    }

