contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint8 maxChange, uint256 epochSize, uint8 changeTolerance) public {
        // Fresh instance: DAO is set, configured == false, so onlySuccessfulProposal short-circuits.
        // The only revert condition inside configureSecurityParameters is changeTolerance >= 100.
        bool reverted;
        try c.configureSecurityParameters(maxChange, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 readEpochSize, uint256 readLastFlashGovernanceAct, uint256 readMax, uint256 readTolerance) = c.security();

        if (changeTolerance >= 100) {
            // Must revert and must leave security unchanged (all zeros at fresh deploy).
            assert(reverted);
            assert(readEpochSize == 0 && readLastFlashGovernanceAct == 0 && readMax == 0 && readTolerance == 0);
        } else {
            // Must not revert and must set all three supplied fields exactly.
            assert(!reverted);
            assert(readEpochSize == epochSize);
            assert(readMax == uint256(maxChange));
            assert(readTolerance == uint256(changeTolerance));
        }
    }

    receive() external payable {}
}

