contract InvMutTest {
    C c;
    address assetAddr;
    uint256 depositAmount;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address target, bool emergency) public payable {
        require(sender != address(0));
        require(target != address(0));
        require(sender != target);

        assetAddr = address(new MockToken());
        depositAmount = 1_000_000;

        MockToken(assetAddr).mint(sender, depositAmount);

        c.configureFlashGovernance(assetAddr, depositAmount, 0, false);

        (address cfgAsset, uint256 cfgAmount, uint256 cfgUnlock, bool cfgBurnable) = c.flashGovernanceConfig();
        (uint256 cfgAssetOk, uint256 cfgAmountOk, , uint256 cfgUnlockOk) = (cfgAsset == assetAddr ? 1 : 0, cfgAmount == depositAmount ? 1 : 0, cfgUnlock, cfgBurnable ? 1 : 0);

        uint256 balBefore = IERC20(assetAddr).balanceOf(address(c));
        uint256 senderBefore = IERC20(assetAddr).balanceOf(sender);

        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = IERC20(assetAddr).balanceOf(address(c));
        uint256 senderAfter = IERC20(assetAddr).balanceOf(sender);

        assert(
            reverted
                ? (balAfter == balBefore && senderAfter == senderBefore)
                : (balAfter == balBefore + cfgAmount && senderAfter == senderBefore - cfgAmount)
        );
    }
}

