contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address dao0, address newDao, bool endConfig) public {
        // Setup: record initial DAO, optionally end configuration as the DAO.
        address oldDAO = c.DAO();
        bool configuredBefore = c.configured();

        // endConfiguration can be called by anyone; only makes sense if not yet configured.
        if (endConfig && !configuredBefore) {
            c.endConfiguration();
        }

        bool configuredNow = c.configured();
        address daoNow = c.DAO();

        // The deciding call: setDAO(newDao) from this contract (msg.sender = InvMutTest).
        bool reverted;
        try c.setDAO(newDao) { reverted = false; } catch { reverted = true; }

        // Rule: setDAO must revert iff DAO is already set, and configuration is finished, and
        // the caller (this test contract) is not the current DAO.
        bool mustRevert = daoNow != address(0) && configuredNow && msg.sender != daoNow;
        assert(reverted == mustRevert);

        // Additionally, when the call succeeds, DAO must equal newDao.
        assert(reverted || c.DAO() == newDao);
    }
}

