        uint8 tol;
        try c.configureSecurityParameters(0, 0, tolerance) {
            tol = tolerance;
        } catch {
            tol = 0;
        }

        // Make msg.sender enabled for enforcement on c. This call does not revert.
        c.setEnforcement(true);

        bool reverted;
        try c.enforceTolerance(v1, v2) {
