        // configuration (the call below reads back only public state).
        bool expectedRevert =
            v1 == v2
                ? false
                : (v1 > v2
                    ? (v2 == 0 ? v1 > 1 : ((v1 - v2) * 100) >= uint256(tol) * v1)
                    : (v1 == 0 ? v2 > 1 : ((v2 - v1) * 100) >= uint256(tol) * v1));

        bool enforcementReadBack = c.enforceLimitsActive(address(this));
        (uint8 storedTolerance, , ) = c.security();

        assert(
            (storedTolerance == tol) &&
            (enforcementReadBack == true) &&
            (reverted == expectedRevert)
        );
    }
}

