    constructor(C _c) {
        c = _c;
    }

    function run(address dao) public payable {
        address beforeDAO = c.DAO();
        bool allowed = beforeDAO != address(0) && beforeDAO == msg.sender;
        bool reverted;
        try c.setDAO(dao) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(allowed ? (!reverted && c.DAO() == dao) : (reverted && c.DAO() == beforeDAO));
    }

    receive() external payable {}
}

