contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address sender,
        address target,
        bool emergency,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address governable
    ) public payable {
        require(asset != address(0), "asset must be a valid address");
        require(sender != address(0), "sender must be a valid address");
        require(target != address(0), "target must be a valid address");
        require(governable != address(0), "governable must be a valid address");
        require(governable != address(c), "governable must not be c");

        // Read the DAO and governer getters before any state changes that could affect them.
        address dao = c.DAO();

        // Configure flash governance via the onlySuccessfulProposal path, which
        // allows calls while configured == false.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Determine whether sender is the DAO (always allowed) or must be
        // separately whitelisted as a governed address.
        bool senderIsDao = (sender == dao);
        if (!senderIsDao) {
            address[] memory governables = new address[](1);
            bool[] memory isGoverned = new bool[](1);
            governables[0] = sender;
            isGoverned[0] = true;
            c.setGoverned(governables, isGoverned);
        }

        // Pre-read public state observable through c,
        // to distinguish a successful call from a no-op call.
        (uint256 preAmount, uint256 preUnlockTime, address preAsset, bool preBurnable) = c.flashGovernanceConfig();
        (uint256 preEpochSize, uint256 preLastAct, uint8 preMaxChange, uint8 preTolerance) = c.security();

        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // All calls above are top-level or read-only except the two that configure the
        // contract. The assert below captures the general unwinding rule:
        // 1) A non-DAO, non-governed sender always reverts.
        // 2) If the call succeeds, the caller was DAO or governed.
        if (!senderIsDao) {
            // Since the test only whitelists sender when not DAO, a non-DAO sender
            // that was not whitelisted would always revert; here it was whitelisted
            // above, so the call must be attempted.
        }

        // The decisive rule: if the caller was not authorized (not DAO and not the
        // whitelisted governed sender we configured), the call must revert. We cover
        // the observable consequences below.
        if (!senderIsDao) {
            // We always whitelisted `sender`, so the flashEnabled modifier is satisfied.
            // The remaining outcome depends on the configured asset's transferFrom and the
            // pending decision unlock state, both reflected in `reverted`.
        }

        // General invariant for the configuring caller:
        // After a successful assertGovernanceApproved, c's security.lastFlashGovernanceAct
        // equals block.timestamp and a pending decision exists for target/sender.
        // After a revert, c's observable security and flash config remain unchanged,
        // except for any effects of the separate configure steps performed above.
        if (!reverted) {
            (, uint256 postLastAct, , ) = c.security();
            assert(postLastAct == block.timestamp);
            (uint256 pAmount, uint256 pUnlockTime, address pAsset, bool pBurnable) = c.pendingFlashDecision(target, sender);
            assert(pAmount == preAmount);
            assert(pAsset == preAsset);
            assert(pBurnable == preBurnable);
            assert(pUnlockTime >= preUnlockTime);
        } else {
            (, uint256 postLastActRevert, , ) = c.security();
            (uint256 pAmountR, uint256 pUnlockTimeR, address pAssetR, bool pBurnableR) = c.pendingFlashDecision(target, sender);
            assert(postLastActRevert == preLastAct);
            assert(pAmountR == 0);
            assert(pAssetR == address(0));
            assert(pBurnableR == false);
            assert(pUnlockTimeR == 0);
        }
    }

    receive() external payable {}
}

