contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public {
        require(changeTolerance < 100, "precondition");

        bool wasConfigured = c.configured();

        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (, , uint8 tol) = c.security();
        bool completed = !reverted;

        assert(
            (wasConfigured && reverted) ||
            (!wasConfigured && completed && tol == changeTolerance)
        );
    }
}

