contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata governables, bool[] calldata isGoverned, uint256 index) public payable {
        require(governables.length == isGoverned.length, "length mismatch");
        require(governables.length > 0, "empty arrays");
        require(index < governables.length, "index out of bounds");

        // The caller must be able to authorize setGoverned. If configured is false, anyone can call.
        // We are the test contract; we need to ensure that our call to setGoverned succeeds.
        // In the deployment, the DAO is set via constructor of Governable. However, the test contract
        // is not the DAO. To make it succeed, we need configured == false. But configured is a public bool.
        // If configured is true, only successful proposal can call setGoverned.
        // ensure we are a successful proposal by making a proposal? We cannot call LimboDAOLike directly.
        // Since the test contract deploys C with a DAO address, and we don't know if that DAO is a real LimboDAOLike.
        // The assumption is that the provided C is already properly set up so that the test contract can call setGoverned.
        // We use the try-catch pattern to capture the success and assert accordingly.

        // Read the DAO address (public getter) and configured
        address dao = c.DAO();
        bool configured = c.configured();

        // We will perform the call and capture whether it succeeds.
        bool reverted;
        try c.setGoverned(governables, isGoverned) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: if the call did not revert, then for the given index, the governed flag matches isGoverned[index].
        // Also, if it reverted, we don't assert about the state change (since it may not have happened).
        // We can also assert that when reverted is false, the flag is exactly as expected.
        assert(reverted || c.governed(governables[index]) == isGoverned[index]);
    }

    receive() external payable {}
}

