        // Setup: configure c so configured() is true and enforceLimitsActive is true for this test contract.
        c.configureSecurityParameters(200, 0, 10);
        c.setEnforcement(true);

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 changeTolerance = 10;
        bool shouldRevert;
        if (v1 > v2) {
            if (v2 == 0) {
                shouldRevert = v1 > 1;
            } else {
                shouldRevert = ((v1 - v2) * 100) >= changeTolerance * v1;
            }
        } else {
            if (v1 == 0) {
                shouldRevert = v2 > 1;
            } else {
                shouldRevert = ((v2 - v1) * 100) >= changeTolerance * v1;
            }
        }

        assert(reverted == shouldRevert);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint8 changeTolerance, uint256 v1, uint256 v2) public {
        require(changeTolerance < 100);

        // Setup: make this test contract the DAO so configureSecurityParameters' onlySuccessfulProposal passes
        // and enable enforcement for this test contract.
        c.setDAO(address(this));
        c.configureSecurityParameters(0, 1, changeTolerance);
        c.setEnforcement(true);

        // Since c.configured() is false (nobody called endConfiguration), enforceTolerance returns early.
