            c.endConfiguration();
        }

        bool reverted;
        try c.setDAO(newDao) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool shouldRevert = !endConfig && configuredBefore && daoBefore != address(this);
        if (shouldRevert) {
            assert(reverted && c.DAO() == daoBefore);
        } else {
            assert(!reverted && c.DAO() == newDao);
        }
    }
}

