contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address[] calldata governables,
        bool[] calldata isGoverned
    ) public payable {
        require(governables.length == isGoverned.length, "lengths differ");

        bool reverted;
        try c.setGoverned(governables, isGoverned) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Build a bitmask of indices where the stored flag matches the input flag.
        // Only meaningful when the call succeeded; if it reverted we skip the loop
        // and assert the implication vacuously (reverted == true).
        bool allMatch = true;
        if (!reverted) {
            for (uint256 i = 0; i < governables.length; i++) {
                if (c.governed(governables[i]) != isGoverned[i]) {
                    allMatch = false;
                    break;
                }
            }
        }

        assert(reverted || allMatch);
    }

    receive() external payable {}
}

