contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public payable {
        uint256 beforeEpochSize;
        uint256 beforeLastFlashGovernanceAct;
        uint8 beforeMaxGovernanceChangePerEpoch;
        uint8 beforeChangeTolerance;
        (beforeEpochSize, beforeLastFlashGovernanceAct, beforeMaxGovernanceChangePerEpoch, beforeChangeTolerance) = c.security();

        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterEpochSize, uint256 afterLastFlashGovernanceAct, uint8 afterMaxGovernanceChangePerEpoch, uint8 afterChangeTolerance) = c.security();

        if (changeTolerance >= 100) {
            assert(reverted);
        } else {
            assert(!reverted
                && afterMaxGovernanceChangePerEpoch == maxGovernanceChangePerEpoch
                && afterEpochSize == epochSize
                && afterChangeTolerance == changeTolerance);
        }
    }

    receive() external payable {}
}

